<template><section class="event-atlas"><div class="atlas-hero"><div><span class="eyebrow">THE WORLD IS YOUR PLAYBOOK</span><h1>Learn from the circuit<span>.</span></h1><p>Big stages. Local scenes. Better event days.</p></div><div class="atlas-count"><b>{{ library.length }}</b><span>SELECTED REFERENCES<br>2024 — 2026</span></div></div><div class="atlas-summary"><article><b>01 / DISCOVER</b><p>Find an event by year, location or name.</p></article><article><b>02 / UNDERSTAND</b><p>See what the source actually verifies.</p></article><article><b>03 / ADAPT</b><p>Use the idea in your own event workflow.</p></article></div><p class="reference-note">Research snapshot · 3 October 2026. This is a selected reference library, not every Tekken 8 event ever held or a live results service. Schedule entries verify announcement only. “Lesson” is our design interpretation; it does not claim the referenced tournament used this software or endorses it.</p><div class="table-toolbar"><input class="search" v-model="query" aria-label="Search event library" placeholder="Search events, regions, ideas…"/><select v-model="year" aria-label="Filter event year"><option value="">All years</option><option>2026</option><option>2025</option><option>2024</option></select><label class="ops-check"><input type="checkbox" v-model="practical"/>With a specific lesson</label><span>{{ filtered.length }} references</span></div><div class="atlas-grid"><article v-for="r in filtered" :key="r.name+r.year" class="atlas-card"><header><span>{{ r.region }}</span><b>{{ r.year }}</b></header><h2>{{ r.name }}</h2><span class="atlas-type">{{ r.type }}</span><p>{{ r.evidence }}</p><div class="atlas-lesson"><small>LESSON / {{ r.feature }}</small><p>{{ r.lesson }}</p></div><a :href="r.source" target="_blank" rel="noopener noreferrer">Read the source ↗</a></article></div><div v-if="!filtered.length" class="org-card small-empty">No references match. Try another name or year.</div><footer class="org-card"><h2>Keep exploring</h2><p>Use the official circuit portal and the community directory for events beyond this snapshot.</p><div class="button-row"><a href="https://tekkenworldtour.com/" target="_blank" rel="noopener noreferrer">Official World Tour ↗</a><a href="https://www.start.gg/search/tournaments?refinementList%5Bevents.videogame.id%5D=49783" target="_blank" rel="noopener noreferrer">Tekken 8 event directory ↗</a></div></footer></section></template>
<script lang="ts">
import {Vue,Component} from 'vue-property-decorator'
import {EVENT_LIBRARY} from './event-library'
@Component
export default class EventLibrary extends Vue {
 library=EVENT_LIBRARY;query='';year='';practical=false
 get filtered(){return this.library.filter(r=>(!this.year||r.year===Number(this.year))&&(!this.practical||r.feature!=='Reference only')&&(r.name+' '+r.region+' '+r.type+' '+r.feature).toLowerCase().includes(this.query.toLowerCase()))}
}
</script>
